# Let's look for any JSON files in the workspace that contain 'input' or 'inp' 
# and check their structure

workspace_path = "/home/USER/runs/paper/qwen-in-glm-h-u1/frozen/seen-6/play/users/u022/system/state/workspace"

inp_files = []
for f in os.listdir(workspace_path):
    if 'inp' in f.lower() or 'input' in f.lower():
        inp_files.append(f)

print(f"Input files found: {inp_files}")

# Also try to find ANY JSON with a grid that has colors 1 and 5
# Based on the goal summary, task-579b1ece has a 24x27 grid with colors {1, 5}

for root, dirs, files in os.walk(workspace_path):
    for f in files:
        if not f.endswith('.json'):
            continue
        full_path = os.path.join(root, f)
        try:
            with open(full_path) as fp:
                content = fp.read().lower()
                # Look for grid with colors 1 and 5
                if 'grid' in content and '"1"' in content and '"5"' in content:
                    # Check dimensions
                    import re
                    matches = re.findall(r'(\d+),\s*"1"', content)
                    if len(matches) > 0:
                        inp_files.append((f, full_path))
        except:
            pass

print(f"\nFiles with grid color 1 and 5: {len(inp_files)}")

# List them
for fname, fpath in inp_files[:10]:
    print(f"  {fpath}")

